import gzip,glob,pandas as pd,csv
def load(f):
    rows=[]
    for l in gzip.open(f,'rt',errors='replace'):
        if l.startswith('!series_matrix_table_begin'): break
        if l.startswith('!Sample'):
            p=next(csv.reader([l.rstrip('\n')],delimiter='\t'))
            rows.append(p)
    cols={}
    for r in rows:
        k=r[0]; i=2
        while k in cols: k=r[0]+str(i); i+=1
        cols[k]=r[1:]
    return pd.DataFrame(cols)
