import gzip,csv,pandas as pd
def load(fn):
    rows=[]
    for l in gzip.open(fn,'rt'):
        if l.startswith('!series_matrix_table_begin'): break
        if l.startswith('!Sample'): rows.append(next(csv.reader([l.rstrip('\n')],delimiter='\t')))
    cols={}
    for r in rows:
        k=r[0];i=2
        while k in cols: k=r[0]+str(i);i+=1
        cols[k]=r[1:]
    return pd.DataFrame(cols)
